import numpy as np
import scipy.stats as st
nan = float('nan')
inf = float('inf')

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    a = np.asarray(x).astype(float)
    r = np.asarray(ref).astype(float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if not (abs(u - v) <= atol + rtol * abs(v) or (u != u and v != v) or u == v):
            print('mismatch', u, v)
            ok = False
    return ok

gm = [3.501332933380932, 3.2647494679881888]
mq = [2.47, 3.65, 4.73]
mq2 = [[1.0502034427428735, 3.801273023374126, 6.972418138352089], [1.2709327383144629, 3.788388496269156, 6.868134778012674], [1.1388998530777197, 3.792360820234355, 6.718524774987525], [1.0272514147863105, 3.8128735622199916, 6.946410579963453]]
mq3 = [2.7399999999999993, 4.459999999999999]
wz = [2.1, 3.4, 2.1, 5.0, 4.2, 3.3, 2.8, 5.0, 4.4, 3.9, 2.2, 5.0]
wz2 = [[5.620906917604419, 5.620906917604419, 2.7515594903585727, 2.039069137409164, 2.039069137409164, 4.850986556389679], [6.261706763029913, 6.261706763029913, 3.5634998985741593, 1.4827854127706428, 1.4827854127706428, 4.013277093964152], [6.531561876197476, 6.531561876197476, 4.410211654623501, 1.7209362614235362, 1.7209362614235362, 3.1745099858452095], [5.9809501247322405, 5.9809501247322405, 5.224246185440176, 2.3568122193271948, 2.3568122193271948, 2.401500938999807]]
tm = [3.689999999999999, 3.477777777777778, 0.8772839506172841, 0.9934507760550819]

x = np.array([2.1, 3.4, 1.9, 5.6, 4.2, 3.3, 2.8, 6.1, 4.4, 3.9, 2.2, 5.0])
y = np.array([1.8, 2.9, 3.1, 4.7, 5.2, 2.6, 3.0, 5.9, 3.5, 4.1, 2.5, 4.4])
xn = x.copy()
xn[2] = nan
xn[7] = nan
yn = y.copy()
yn[4] = nan
X2 = np.cos(np.arange(24.)).reshape(4, 6) * 3 + 4

from scipy.stats import mstats

@test
def test_mstats():
    assert close([mstats.gmean(x), mstats.hmean(x)], gm)
    assert close(mstats.mquantiles(x), mq)
    assert close(mstats.mquantiles(X2, prob=[0.1, 0.5, 0.9], axis=1), mq2)
    assert close(mstats.mquantiles(x, prob=[0.3, 0.7], alphap=0.0, betap=0.0), mq3)
    assert close(mstats.winsorize(x, limits=(0.1, 0.2)), wz)
    assert close(mstats.winsorize(X2, limits=0.25, axis=1), wz2)
    out = [mstats.trimmed_mean(x, (0.1, 0.1)), mstats.trimmed_mean(x, (2.0, 5.0), relative=False),
           mstats.trimmed_var(x, (0.1, 0.2)), mstats.trimmed_std(x, (0.1, 0.2), ddof=1)]
    assert close(out, tm)

test_mstats()
